<?php
declare(strict_types=1);
require_once __DIR__ . '/../middleware/role-check.php';
require_once __DIR__ . '/../config/database.php';
header('Content-Type: application/json; charset=utf-8');
requireMarketplaceRole();
if ($_SERVER['REQUEST_METHOD'] !== 'GET') { http_response_code(405); echo json_encode(['success'=>false,'message'=>'Method not allowed.']); exit; }
$role = getAuthenticatedRole(); $viewer=(int)getAuthenticatedUserId(); $params=[':role'=>$role,':viewer'=>$viewer];
$sql = "SELECT l.id,l.asking_price,l.condition_grade,l.condition_description,l.defects,l.reported_ownership_months,l.created_at,i.assigned_at,i.purchase_price original_purchase_price,e.id equipment_id,e.name,e.description,e.brand,e.image_url,e.access_role,e.price original_price,c.name category,u.handle seller_handle,u.full_name seller_name,(SELECT GROUP_CONCAT(r.character_role ORDER BY r.character_role SEPARATOR ',') FROM equipment_character_roles r WHERE r.equipment_id=e.id) compatible_roles FROM resale_listings l JOIN inventory i ON i.id=l.inventory_id JOIN equipment e ON e.id=i.equipment_id JOIN users u ON u.id=l.seller_id LEFT JOIN categories c ON c.id=e.category_id WHERE l.status='active' AND l.seller_id<>:viewer AND (e.access_role='common' OR e.access_role=:role)";
$q=trim((string)($_GET['q']??'')); if($q!==''){$sql.=' AND (e.name LIKE :q OR e.description LIKE :q OR l.condition_description LIKE :q)';$params[':q']='%'.mb_substr($q,0,100).'%';}
$condition=strtolower((string)($_GET['condition']??''));if(in_array($condition,['like_new','good','fair','poor'],true)){$sql.=' AND l.condition_grade=:condition';$params[':condition']=$condition;}
$characterRole=strtolower((string)($_GET['character_role']??''));if(in_array($characterRole,['mage','fighter','marksman','tank','support'],true)){$sql.=' AND EXISTS(SELECT 1 FROM equipment_character_roles r WHERE r.equipment_id=e.id AND r.character_role=:character_role)';$params[':character_role']=$characterRole;}
$sort=(string)($_GET['sort']??'newest');$sql.=$sort==='price_asc'?' ORDER BY l.asking_price ASC,l.id DESC':($sort==='price_desc'?' ORDER BY l.asking_price DESC,l.id DESC':' ORDER BY l.created_at DESC,l.id DESC');$sql.=' LIMIT 100';
try{$stmt=$pdo->prepare($sql);$stmt->execute($params);$items=$stmt->fetchAll(PDO::FETCH_ASSOC);foreach($items as &$item){$months=$item['assigned_at']!==null?max(0,(int)$pdo->query('SELECT TIMESTAMPDIFF(MONTH,'. $pdo->quote((string)$item['assigned_at']) .',CURRENT_TIMESTAMP)')->fetchColumn()):(int)($item['reported_ownership_months']??0);$item['ownership_months']=$months;$item['original_purchase_date']=$item['assigned_at'];$item['ownership_label']=$item['assigned_at']!==null?'Calculated from recorded acquisition date':'Seller-reported; not independently verified';$item['compatible_roles']=empty($item['compatible_roles'])?[]:explode(',',$item['compatible_roles']);$item['asking_price']=(float)$item['asking_price'];$item['original_price']=(float)$item['original_price'];$item['original_purchase_price']=(float)$item['original_purchase_price'];}unset($item);echo json_encode(['success'=>true,'listings'=>$items]);}catch(Throwable $e){error_log('AETHERYX resale list: '.$e->getMessage());http_response_code(500);echo json_encode(['success'=>false,'message'=>'Unable to load resale listings.']);}
